  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Base, unscheduled ADI kernel. This is a direct, readable translation
# of the PolyBench/C reference implementation.
@proc
def kernel_adi_base(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # We update the interior points 1..n-2 in both dimensions.
    assert n > 2

    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Coefficients precomputed from mul1 and mul2 (which are derived
    # from DX, DY, DT in the C driver). These match the PolyBench
    # reference.
    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    for t in seq(1, tsteps + 1):
        # ---------------------------------------------------------------------
        # Column sweep: tridiagonal solve along the j dimension for each
        # column i. This stage *reads* u and *writes* v (plus temporary
        # factors p and q).
        # ---------------------------------------------------------------------
        for i in seq(1, n - 1):
            # Forward sweep: initialize boundary at j = 0.
            v[0, i] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Forward elimination along j.
            for j in seq(1, n - 1):
                # Hoist the common denominator to a scalar to improve
                # reuse and register allocation.
                denom_col: DATA_TYPE
                denom_col = a * p[i, j - 1] + b

                p[i, j] = -c / denom_col
                q[i, j] = (
                    -d * u[j, i - 1]
                    + (1.0 + 2.0 * d) * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / denom_col

            # Backward substitution: boundary at j = n - 1.
            v[n - 1, i] = 1.0
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

        # ---------------------------------------------------------------------
        # Row sweep: tridiagonal solve along the i dimension for each
        # row j. This stage *reads* v and *writes* u (plus p and q again).
        # ---------------------------------------------------------------------
        for i in seq(1, n - 1):
            # Forward sweep: initialize boundary at j = 0.
            u[i, 0] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = u[i, 0]

            # Forward elimination along j.
            for j in seq(1, n - 1):
                denom_row: DATA_TYPE
                denom_row = d * p[i, j - 1] + e

                p[i, j] = -f / denom_row
                q[i, j] = (
                    -a * v[i - 1, j]
                    + (1.0 + 2.0 * a) * v[i, j]
                    - c * v[i + 1, j]
                    - d * q[i, j - 1]
                ) / denom_row

            # Backward substitution along j.
            u[i, n - 1] = 1.0
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )


# -----------------------------------------------------------------------------
# Scheduling: expose coarse-grain parallelism over the spatial dimension.
#
# Both sweeps have their work decomposed over the outer loop in i:
#  - For fixed t, every iteration in the outer "i" loop of the column
#    sweep touches a distinct column of v, p, and q, and only *reads*
#    from u. These iterations are independent and can be run in parallel.
#  - For the row sweep, each "i" iteration updates a distinct row of u
#    and only reads from neighboring rows of v, which is read-only here.
#
# We parallelize these two outer "i" loops. Exo lowers this to OpenMP
# pragmas in the generated C code.
# -----------------------------------------------------------------------------

kernel_adi_sched = kernel_adi_base

# Parallelize the outer "i" loop in the column sweep.
kernel_adi_sched = parallelize_loop(kernel_adi_sched, "i")

# Parallelize the outer "i" loop in the row sweep
# (the second occurrence of an "i" loop in the procedure).
kernel_adi_sched = parallelize_loop(kernel_adi_sched, "i #1")

# Give the scheduled kernel the externally visible name expected by
# the C driver and the generated header: kernel_adi.
kernel_adi = rename(kernel_adi_sched, "kernel_adi")

